export const getApproveLearningProposalUrl = (
  organizationId: string,
  proposalId: string,
  params?: ApproveLearningProposalParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/v2/organizations/${encodeURIComponent(String(organizationId))}/settings/learning/proposals/${encodeURIComponent(String(proposalId))}/approve?${stringifiedParams}`
    : `/api/v2/organizations/${encodeURIComponent(String(organizationId))}/settings/learning/proposals/${encodeURIComponent(String(proposalId))}/approve`;
};

/**
 * Approve a proposal in the space every Bot learns into, or in one Bot's own, which publishes the skill change to every Bot that learns there. Approving it again answers the same review. Only an administrator may. Recorded on the audit trail.
 * @summary Approve a proposal in a space
 */
export const approveLearningProposal = async (
  organizationId: string,
  proposalId: string,
  headers: ApproveLearningProposalHeaders,
  params?: ApproveLearningProposalParams,
  options?: Parameters<typeof apiRequest>[1],
): Promise<LearningReview> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiRequest<LearningReview>(
    getApproveLearningProposalUrl(organizationId, proposalId, params),
    {
      ...options,
      method: "POST",
      headers: { ...headers, ...getHeaders(options?.headers) },
    },
  );
};

