/**
 * Start Learning over the space every Bot learns into, or over one Bot's own, on every finished conversation not yet learned from. A run already going is answered instead of starting another. Only an administrator may. Recorded on the audit trail.
 * @summary Learn now in a space
 */
export const startOrganizationLearningRun = async (
  organizationId: string,
  headers: StartOrganizationLearningRunHeaders,
  params?: StartOrganizationLearningRunParams,
  options?: Parameters<typeof apiRequest>[1],
): Promise<LearningRun> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiRequest<LearningRun>(
    getStartOrganizationLearningRunUrl(organizationId, params),
    {
      ...options,
      method: "POST",
      headers: { ...headers, ...getHeaders(options?.headers) },
    },
  );
};

